import React from "react";
import { useNavigate } from "react-router-dom";
import "../styles/SpendingPriority.css"; // keep your existing css file

function SpendingPriority() {
  const navigate = useNavigate();

  const handleContinue = () => {
    navigate("/budget");
  };

  return (
    <div className="spending-container">
      <div className="spending-card">
        <h2 className="spending-title">Spending Priorities</h2>

        {/* KEEP YOUR EXISTING OPTIONS / CONTENT EXACTLY SAME */}

        <button className="next-button" onClick={handleContinue}>
          Continue
        </button>
      </div>
    </div>
  );
}

export default SpendingPriority;
